python3 << 'EOF'
import openpyxl
wb = openpyxl.load_workbook('data/gaia/raw/65afbc8a-89ca-4ad5-8d62-355bb401f61d.xlsx')
ws = wb.active

# Print all cell values and check for any non-None
print("All cells with values:")
for row in ws.iter_rows():
    for cell in row:
        if cell.value is not None:
            print(f"  {cell.coordinate}: {cell.value}")

# Also check for any merged cells
print("\nMerged cells:", ws.merged_cells)

# Print the full color grid as a matrix
print("\nColor grid (A-I, rows 1-20):")
color_map = {}
for row in ws.iter_rows():
    for cell in row:
        fill = cell.fill
        if fill and fill.fgColor and fill.fgColor.type == 'rgb':
            color_map[(cell.row, cell.column)] = fill.fgColor.rgb

for r in range(1, 21):
    row_colors = []
    for c in range(1, 10):
        color = color_map.get((r, c), 'NONE')
        # Abbreviate colors
        if color == 'FF0099FF':
            row_colors.append('BLUE')
        elif color == 'FF92D050':
            row_colors.append('GRN ')
        elif color == 'FFFFFF00':
            row_colors.append('YLW ')
        elif color == 'FFF478A7':
            row_colors.append('PNK ')
        else:
            row_colors.append(color[:6] if color != 'NONE' else 'NONE')
    print(f"Row {r:2d}: {' | '.join(row_colors)}")
