dists = [(0,6,24),(0,12,18),(1,7,22),(2,8,20),(2,11,17),(3,9,18),(4,10,16),(5,11,14),(6,9,15),(6,12,12),(7,10,13),(8,8,14)]

def winnings_antisorted(p, q, r, a, b, c):
    return r*(r<=a) + q*(q<=b) + p*(p<=c)

def guarantee(p, q, r):
    p,q,r = sorted([p,q,r])
    return min(winnings_antisorted(p,q,r,a,b,c) for a,b,c in dists)

print(f'Guarantee (6,6,6): {guarantee(6,6,6)}')

print('Per distribution for (6,6,6):')
for d in dists:
    w = winnings_antisorted(6,6,6,*d)
    print(f'  {d}: wins {w}')

best = 0
best_guesses = None
for p in range(31):
    for q in range(p, 31):
        for r in range(q, 31):
            g = guarantee(p, q, r)
            if g > best:
                best = g
                best_guesses = (p, q, r)
print(f'\nBest possible guarantee: {best} with guesses {best_guesses}')
